export function reportUnknownAttrs(attrs, known, where, passName, ctx) {
    for (const key of Object.keys(attrs)) {
        if (!known.has(key)) {
            ctx.diagnostics.push(`${where}: unhandled attribute "${key}" — the export dialect grew; extend ${passName} deliberately`);
        }
    }
}
export function stringList(attrs, key, where, ctx) {
    const raw = attrs[key];
    if (raw === undefined)
        return undefined;
    if (!Array.isArray(raw) || raw.some((value) => typeof value !== "string")) {
        ctx.diagnostics.push(`${where}: ${key} is not a string list; dropped`);
        return undefined;
    }
    return raw;
}
